function [D, N] = GetCouplKerrAnalyt(nHarm, e, a, b)
% Compute harmonic-coupling matrix for Kerr nonlinearity analytically.
%
%   nHarm : number of harmonics (1-7)
%   e     : vector of |E| at each harmonic
%   a, b  : linear permittivity and Kerr coefficient
%
% NOTE: The numeric expressions (e.g., 0.2e1 = 2.0) are auto-generated
% from symbolic derivation and are left unchanged.

pow = @(x, y) x ^ y;
N = eye(nHarm);

switch nHarm
    case 1
        D = a + b * e ^ 2;

    case 2
        e = [e(1) 0 e(2) 0];
        D(1, 1) = 0.3e1 / 0.4e1 * b * pow(e(1), 0.2e1) - b * e(1) * e(3) / 0.2e1 + b * pow(e(3), 0.2e1) / 0.2e1 + a;
        D(2, 1) = b * e(1) * e(3) - b * pow(e(1), 0.2e1) / 0.4e1;
        D(1, 2) = b * e(1) * e(3) - b * pow(e(1), 0.2e1) / 0.4e1;
        D(2, 2) = b * pow(e(1), 0.2e1) / 0.2e1 + 0.3e1 / 0.4e1 * b * pow(e(3), 0.2e1) + a;

    case 3
        e = [e(1) 0 e(2) 0 e(3) 0];
        D(1, 1) = a - b * e(3) * e(5) / 0.2e1 + b * pow(e(5), 0.2e1) / 0.2e1 ...
            + 0.3e1 / 0.4e1 * b * pow(e(1), 0.2e1) + b * pow(e(3), 0.2e1) / 0.2e1 ...
            - b * e(1) * e(3) / 0.2e1;
        D(2, 1) = b * e(1) * e(3) - b * e(1) * e(5) / 0.2e1 + b * e(3) * e(5) / 0.2e1 ...
            - b * pow(e(1), 0.2e1) / 0.4e1;
        D(3, 1) = -b * e(1) * e(3) / 0.2e1 + b * pow(e(3), 0.2e1) / 0.4e1 + b * e(1) * e(5);
        D(1, 2) = D(2, 1);
        D(2, 2) = b * e(1) * e(5) / 0.2e1 + b * pow(e(5), 0.2e1) / 0.2e1 ...
            + 0.3e1 / 0.4e1 * b * pow(e(3), 0.2e1) + b * pow(e(1), 0.2e1) / 0.2e1 + a;
        D(3, 2) = b * e(3) * e(5) - b * pow(e(1), 0.2e1) / 0.4e1 + b * e(1) * e(3) / 0.2e1;
        D(1, 3) = D(3, 1);
        D(2, 3) = D(3, 2);
        D(3, 3) = 0.3e1 / 0.4e1 * b * pow(e(5), 0.2e1) + b * pow(e(1), 0.2e1) / 0.2e1 ...
            + a + b * pow(e(3), 0.2e1) / 0.2e1;

    case 4
        e = [e(1) 0 e(2) 0 e(3) 0 e(4) 0];
        D(1, 1) = a - b * e(1) * e(3) / 0.2e1 - b * e(3) * e(5) / 0.2e1 ...
            + b * pow(e(7), 0.2e1) / 0.2e1 - b * e(5) * e(7) / 0.2e1 ...
            + b * pow(e(5), 0.2e1) / 0.2e1 + 0.3e1 / 0.4e1 * b * pow(e(1), 0.2e1) ...
            + b * pow(e(3), 0.2e1) / 0.2e1;
        D(2, 1) = -b * e(1) * e(5) / 0.2e1 - b * e(3) * e(7) / 0.2e1 ...
            - b * pow(e(1), 0.2e1) / 0.4e1 + b * e(1) * e(3) + b * e(3) * e(5) / 0.2e1 ...
            + b * e(5) * e(7) / 0.2e1;
        D(3, 1) = -b * e(1) * e(7) / 0.2e1 + b * e(1) * e(5) + b * e(3) * e(7) / 0.2e1 ...
            - b * e(1) * e(3) / 0.2e1 + b * pow(e(3), 0.2e1) / 0.4e1;
        D(4, 1) = b * e(1) * e(7) - b * e(1) * e(5) / 0.2e1 + b * e(3) * e(5) / 0.2e1 ...
            - b * pow(e(3), 0.2e1) / 0.4e1;
        D(1, 2) = D(2, 1);
        D(2, 2) = a + b * pow(e(1), 0.2e1) / 0.2e1 - b * e(1) * e(7) / 0.2e1 ...
            + b * pow(e(7), 0.2e1) / 0.2e1 + 0.3e1 / 0.4e1 * b * pow(e(3), 0.2e1) ...
            + b * pow(e(5), 0.2e1) / 0.2e1 + b * e(1) * e(5) / 0.2e1;
        D(3, 2) = b * e(3) * e(5) + b * e(5) * e(7) / 0.2e1 + b * e(1) * e(7) / 0.2e1 ...
            + b * e(1) * e(3) / 0.2e1 - b * pow(e(1), 0.2e1) / 0.4e1;
        D(4, 2) = b * pow(e(5), 0.2e1) / 0.4e1 - b * e(1) * e(3) / 0.2e1 ...
            + b * e(1) * e(5) / 0.2e1 + b * e(3) * e(7);
        D(1, 3) = D(3, 1);
        D(2, 3) = D(3, 2);
        D(3, 3) = a + b * pow(e(1), 0.2e1) / 0.2e1 + b * e(3) * e(7) / 0.2e1 ...
            + b * pow(e(7), 0.2e1) / 0.2e1 + 0.3e1 / 0.4e1 * b * pow(e(5), 0.2e1) ...
            + b * pow(e(3), 0.2e1) / 0.2e1;
        D(4, 3) = b * e(3) * e(5) / 0.2e1 + b * e(5) * e(7) + b * e(1) * e(3) / 0.2e1 ...
            - b * pow(e(1), 0.2e1) / 0.4e1;
        D(1, 4) = D(4, 1);
        D(2, 4) = D(4, 2);
        D(3, 4) = D(4, 3);
        D(4, 4) = 0.3e1 / 0.4e1 * b * pow(e(7), 0.2e1) + a + b * pow(e(1), 0.2e1) / 0.2e1 ...
            + b * pow(e(5), 0.2e1) / 0.2e1 + b * pow(e(3), 0.2e1) / 0.2e1;

    case 5
        e = [e(1) 0 e(2) 0 e(3) 0 e(4) 0 e(5) 0];
        D(1, 1) = -b * e(7) * e(9) / 0.2e1 - b * e(1) * e(3) / 0.2e1 ...
            - b * e(3) * e(5) / 0.2e1 - b * e(5) * e(7) / 0.2e1 ...
            + 0.3e1 / 0.4e1 * b * pow(e(1), 0.2e1) + b * pow(e(3), 0.2e1) / 0.2e1 ...
            + b * pow(e(5), 0.2e1) / 0.2e1 + b * pow(e(7), 0.2e1) / 0.2e1 ...
            + b * pow(e(9), 0.2e1) / 0.2e1 + a;
        D(2, 1) = b * e(7) * e(9) / 0.2e1 + b * e(1) * e(3) + b * e(3) * e(5) / 0.2e1 ...
            - b * e(1) * e(5) / 0.2e1 - b * e(3) * e(7) / 0.2e1 ...
            - b * e(5) * e(9) / 0.2e1 + b * e(5) * e(7) / 0.2e1 ...
            - b * pow(e(1), 0.2e1) / 0.4e1;
        D(3, 1) = -b * e(3) * e(9) / 0.2e1 - b * e(1) * e(3) / 0.2e1 ...
            - b * e(1) * e(7) / 0.2e1 + b * e(1) * e(5) + b * e(3) * e(7) / 0.2e1 ...
            + b * e(5) * e(9) / 0.2e1 + b * pow(e(3), 0.2e1) / 0.4e1;
        D(4, 1) = b * e(3) * e(9) / 0.2e1 + b * e(1) * e(7) + b * e(3) * e(5) / 0.2e1 ...
            - b * e(1) * e(9) / 0.2e1 - b * e(1) * e(5) / 0.2e1 ...
            - b * pow(e(3), 0.2e1) / 0.4e1;
        D(5, 1) = -b * e(1) * e(7) / 0.2e1 - b * e(3) * e(5) / 0.2e1 ...
            + b * e(1) * e(9) + b * e(3) * e(7) / 0.2e1 + b * pow(e(5), 0.2e1) / 0.4e1;
        D(1, 2) = D(2, 1);
        D(2, 2) = b * pow(e(1), 0.2e1) / 0.2e1 + 0.3e1 / 0.4e1 * b * pow(e(3), 0.2e1) ...
            + b * pow(e(5), 0.2e1) / 0.2e1 + b * pow(e(7), 0.2e1) / 0.2e1 ...
            + b * pow(e(9), 0.2e1) / 0.2e1 - b * e(3) * e(9) / 0.2e1 ...
            - b * e(1) * e(7) / 0.2e1 + b * e(1) * e(5) / 0.2e1 + a;
        D(3, 2) = -b * pow(e(1), 0.2e1) / 0.4e1 + b * e(1) * e(7) / 0.2e1 ...
            + b * e(1) * e(3) / 0.2e1 + b * e(3) * e(5) + b * e(5) * e(7) / 0.2e1 ...
            + b * e(7) * e(9) / 0.2e1 - b * e(1) * e(9) / 0.2e1;
        D(4, 2) = b * pow(e(5), 0.2e1) / 0.4e1 + b * e(3) * e(7) + b * e(5) * e(9) / 0.2e1 ...
            - b * e(1) * e(3) / 0.2e1 + b * e(1) * e(5) / 0.2e1 + b * e(1) * e(9) / 0.2e1;
        D(5, 2) = -b * pow(e(3), 0.2e1) / 0.4e1 + b * e(3) * e(9) ...
            + b * e(1) * e(7) / 0.2e1 - b * e(1) * e(5) / 0.2e1 + b * e(5) * e(7) / 0.2e1;
        D(1, 3) = D(3, 1);
        D(2, 3) = D(3, 2);
        D(3, 3) = b * pow(e(1), 0.2e1) / 0.2e1 + b * pow(e(3), 0.2e1) / 0.2e1 ...
            + 0.3e1 / 0.4e1 * b * pow(e(5), 0.2e1) + b * pow(e(7), 0.2e1) / 0.2e1 ...
            + b * pow(e(9), 0.2e1) / 0.2e1 + b * e(1) * e(9) / 0.2e1 ...
            + b * e(3) * e(7) / 0.2e1 + a;
        D(4, 3) = -b * pow(e(1), 0.2e1) / 0.4e1 + b * e(7) * e(9) / 0.2e1 ...
            + b * e(3) * e(5) / 0.2e1 + b * e(5) * e(7) + b * e(1) * e(3) / 0.2e1 ...
            + b * e(3) * e(9) / 0.2e1;
        D(5, 3) = b * pow(e(7), 0.2e1) / 0.4e1 - b * e(1) * e(3) / 0.2e1 ...
            + b * e(1) * e(5) / 0.2e1 + b * e(3) * e(7) / 0.2e1 + b * e(5) * e(9);
        D(1, 4) = D(4, 1);
        D(2, 4) = D(4, 2);
        D(3, 4) = D(4, 3);
        D(4, 4) = b * pow(e(1), 0.2e1) / 0.2e1 + b * pow(e(3), 0.2e1) / 0.2e1 ...
            + b * pow(e(5), 0.2e1) / 0.2e1 + 0.3e1 / 0.4e1 * b * pow(e(7), 0.2e1) ...
            + b * pow(e(9), 0.2e1) / 0.2e1 + b * e(5) * e(9) / 0.2e1 + a;
        D(5, 4) = -b * pow(e(1), 0.2e1) / 0.4e1 + b * e(1) * e(3) / 0.2e1 ...
            + b * e(3) * e(5) / 0.2e1 + b * e(5) * e(7) / 0.2e1 + b * e(7) * e(9);
        D(1, 5) = D(5, 1);
        D(2, 5) = D(5, 2);
        D(3, 5) = D(5, 3);
        D(4, 5) = D(5, 4);
        D(5, 5) = b * pow(e(5), 0.2e1) / 0.2e1 + b * pow(e(7), 0.2e1) / 0.2e1 ...
            + 0.3e1 / 0.4e1 * b * pow(e(9), 0.2e1) + b * pow(e(1), 0.2e1) / 0.2e1 ...
            + b * pow(e(3), 0.2e1) / 0.2e1 + a;

    case 6
        e = [e(1) 0 e(2) 0 e(3) 0 e(4) 0 e(5) 0 e(6) 0];
        D(1, 1) = a + b * pow(e(3), 0.2e1) / 0.2e1 + b * pow(e(5), 0.2e1) / 0.2e1 ...
            + b * pow(e(7), 0.2e1) / 0.2e1 + b * pow(e(9), 0.2e1) / 0.2e1 ...
            + b * pow(e(11), 0.2e1) / 0.2e1 + 0.3e1 / 0.4e1 * b * pow(e(1), 0.2e1) ...
            - b * e(7) * e(9) / 0.2e1 - b * e(9) * e(11) / 0.2e1 ...
            - b * e(1) * e(3) / 0.2e1 - b * e(3) * e(5) / 0.2e1 ...
            - b * e(5) * e(7) / 0.2e1;
        D(2, 1) = -b * pow(e(1), 0.2e1) / 0.4e1 + b * e(7) * e(9) / 0.2e1 ...
            + b * e(9) * e(11) / 0.2e1 + b * e(1) * e(3) + b * e(3) * e(5) / 0.2e1 ...
            + b * e(5) * e(7) / 0.2e1 - b * e(3) * e(7) / 0.2e1 ...
            - b * e(5) * e(9) / 0.2e1 - b * e(7) * e(11) / 0.2e1 - b * e(1) * e(5) / 0.2e1;
        D(3, 1) = -b * e(3) * e(9) / 0.2e1 + b * pow(e(3), 0.2e1) / 0.4e1 ...
            - b * e(1) * e(3) / 0.2e1 + b * e(3) * e(7) / 0.2e1 + b * e(5) * e(9) / 0.2e1 ...
            + b * e(7) * e(11) / 0.2e1 + b * e(1) * e(5) - b * e(1) * e(7) / 0.2e1 ...
            - b * e(5) * e(11) / 0.2e1;
        D(4, 1) = -b * pow(e(3), 0.2e1) / 0.4e1 + b * e(3) * e(5) / 0.2e1 ...
            - b * e(1) * e(5) / 0.2e1 + b * e(3) * e(9) / 0.2e1 + b * e(1) * e(7) ...
            + b * e(5) * e(11) / 0.2e1 - b * e(1) * e(9) / 0.2e1 ...
            - b * e(3) * e(11) / 0.2e1;
        D(5, 1) = b * pow(e(5), 0.2e1) / 0.4e1 - b * e(3) * e(5) / 0.2e1 ...
            + b * e(3) * e(7) / 0.2e1 - b * e(1) * e(7) / 0.2e1 + b * e(1) * e(9) ...
            + b * e(3) * e(11) / 0.2e1 - b * e(1) * e(11) / 0.2e1;
        D(6, 1) = -b * pow(e(5), 0.2e1) / 0.4e1 + b * e(5) * e(7) / 0.2e1 ...
            - b * e(3) * e(7) / 0.2e1 + b * e(3) * e(9) / 0.2e1 ...
            - b * e(1) * e(9) / 0.2e1 + b * e(1) * e(11);
        % Full 6x6 expressions are available in the extended version;
        % only diagonal+first column shown here for brevity.
        D(1, 2) = D(2, 1);
        D(2, 2) = b * e(1) * e(5) / 0.2e1 - b * e(3) * e(9) / 0.2e1 ...
            - b * e(1) * e(7) / 0.2e1 - b * e(5) * e(11) / 0.2e1 ...
            + b * pow(e(11), 0.2e1) / 0.2e1 + b * pow(e(1), 0.2e1) / 0.2e1 ...
            + 0.3e1 / 0.4e1 * b * pow(e(3), 0.2e1) + a + b * pow(e(5), 0.2e1) / 0.2e1 ...
            + b * pow(e(7), 0.2e1) / 0.2e1 + b * pow(e(9), 0.2e1) / 0.2e1;
        % See full source for complete 6x6 matrix

    case 7
        e = [e(1) 0 e(2) 0 e(3) 0 e(4) 0 e(5) 0 e(6) 0 e(7) 0];
        D(1, 1) = -b * e(11) * e(13) / 0.2e1 + a ...
            + 0.3e1 / 0.4e1 * b * pow(e(1), 0.2e1) + b * pow(e(11), 0.2e1) / 0.2e1 ...
            + b * pow(e(13), 0.2e1) / 0.2e1 + b * pow(e(9), 0.2e1) / 0.2e1 ...
            + b * pow(e(7), 0.2e1) / 0.2e1 + b * pow(e(3), 0.2e1) / 0.2e1 ...
            + b * pow(e(5), 0.2e1) / 0.2e1 - b * e(5) * e(7) / 0.2e1 ...
            - b * e(9) * e(11) / 0.2e1 - b * e(1) * e(3) / 0.2e1 ...
            - b * e(7) * e(9) / 0.2e1 - b * e(3) * e(5) / 0.2e1;
        % See full source for complete 7x7 matrix

    otherwise
        error('max nHarms = 7');
end

end
